    return DeleteStmt(table, where)

def parse(tokens: list[Token]) -> Statement:
    if not tokens or tokens[0].type == TokenType.EOF:
        raise SQLSyntaxError("No statement found")
    if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "CREATE":
        stmt = _parse_create_table_stmt(tokens)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "DROP":
        stmt = _parse_drop_table_stmt(tokens)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "INSERT":
        stmt = _parse_insert_stmt(tokens)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "SELECT":
        stmt = _parse_select_stmt(tokens)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "DELETE":
        stmt = _parse_delete_stmt(tokens)
    else:
        raise SQLSyntaxError(f"Unknown statement: {tokens[0].value}")
    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
        _consume_token(tokens, TokenType.OPERATOR, ";")
    _consume_token(tokens, TokenType.EOF)
    return stmt

def parse_script(tokens: list[Token]) -> list[Statement]:
    stmts = []
    while tokens and tokens[0].type != TokenType.EOF:
        try:
            stmt = parse(tokens)
            stmts.append(stmt)
        except SQLSyntaxError:
            while tokens and tokens[0].type != TokenType.EOF and tokens[0].type != TokenType.OPERATOR and tokens[0].value != ";":
